def find_missing_positive(arr):
    n = len(arr)
    i = 0
    while i < n:
        # Determine the correct position for arr[i]
        # The correct position for value v (if 1 <= v <= n) is v - 1
        val = arr[i]
        if 1 <= val <= n and arr[i] != arr[val - 1]:
            arr[i], arr[val - 1] = arr[val - 1], arr[i]
        else:
            i += 1

    # Find the first index where the value is not index + 1
    for i in range(n):
        if arr[i] != i + 1:
            return i + 1

    # If all positions are correct, the missing positive is n + 1
    return n + 1
