def flatten_data(data):
    result = []

    def is_iterable(obj):
        return isinstance(obj, (list, tuple, set))

    def process_item(item):
        if item is None:
            return
        if callable(item):
            result.append(item())
            return
        if is_iterable(item):
            for sub in item:
                process_item(sub)
        else:
            result.append(item)

    if data is None:
        return result

    process_item(data)
    return result
