def can_combine(element1, element2):
    # Normalize inputs to ensure they are within 1-14
    e1, e2 = element1, element2

    # Rule 1: Elements 1 through 5 can only combine with themselves or with element 5
    if 1 <= e1 <= 5 and 1 <= e2 <= 5:
        if e1 == e2 or e1 == 5 or e2 == 5:
            return True
        else:
            return False

    # Rule 2: Element 6 can only combine with element 7
    if (e1 == 6 and e2 == 7) or (e1 == 7 and e2 == 6):
        return True

    # Rule 3: Element 8 can combine with any element less than 14
    # Result is (8 + x) % 14, with 0 treated as 14. But we only care about combinability.
    if e1 == 8 and 1 <= e2 < 14:
        return True
    if e2 == 8 and 1 <= e1 < 14:
        return True

    # No other combinations are permitted
    return False
