def are_identical_trees(tree1, tree2):
    # Both nodes are None -> identical
    if tree1 is None and tree2 is None:
        return True
    # One is None and the other is not -> not identical
    if tree1 is None or tree2 is None:
        return False
    # Values differ -> not identical
    if tree1.val != tree2.val:
        return False
    # Recursively check left and right subtrees
    return (are_identical_trees(tree1.left, tree2.left) and
            are_identical_trees(tree1.right, tree2.right))
