import os

def encrypt_and_write_text(text: str, abspath: str, encoding: str = "utf-8", key: int = 1) -> int:
    def shift_char(c: str, key: int) -> str:
        if not c.isalpha():
            return c
        base = ord('A') if c.isupper() else ord('a')
        offset = ord(c) - base
        shifted = (offset + key) % 26
        return chr(base + shifted)

    encrypted_chars = []
    current_word = []

    for char in text:
        if char == ' ':
            if current_word:
                for c in current_word:
                    encrypted_chars.append(shift_char(c, key))
                current_word = []
            encrypted_chars.append(char)
        else:
            current_word.append(char)

    if current_word:
        for c in current_word:
            encrypted_chars.append(shift_char(c, key))

    encrypted_text = ''.join(encrypted_chars)

    with open(abspath, 'w', encoding=encoding) as f:
        f.write(encrypted_text)

    return len(encrypted_text.encode(encoding))
```

