def fibonacci(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    memo = {}

    def fib(k):
        if k in memo:
            return memo[k]
        if k <= 1:
            memo[k] = k
        else:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]

    return fib(n)
