def search_sorted_grid(grid, target):
    if not grid or not grid[0]:
        return (-1, -1)

    rows = len(grid)
    cols = len(grid[0])

    # Start from the top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        current = grid[row][col]
        if current == target:
            return (row, col)
        elif current < target:
            # Move down because all elements to the left in this row are smaller
            row += 1
        else:
            # Move left because all elements below in this column are larger
            col -= 1

    return (-1, -1)
```

