def update_inventory(inventory, sales):
    # Create a copy of the inventory to avoid modifying the original
    updated_inventory = dict(inventory)

    # Count sales for each product
    sales_count = {}
    for product in sales:
        sales_count[product] = sales_count.get(product, 0) + 1

    # Subtract sales from inventory
    for product, count in sales_count.items():
        if product in updated_inventory:
            updated_inventory[product] -= count
            # Optionally, remove products with zero or negative stock
            if updated_inventory[product] <= 0:
                updated_inventory.pop(product)

    return updated_inventory
