def lcs_length(s1: str, s2: str) -> int:
    def helper(i: int, j: int) -> int:
        # Base case: if either index is out of bounds, LCS length is 0
        if i == 0 or j == 0:
            return 0
        # If characters match, include this character and move both indices back
        if s1[i - 1] == s2[j - 1]:
            return 1 + helper(i - 1, j - 1)
        # If they don't match, take the maximum of excluding one character from either string
        else:
            return max(helper(i - 1, j), helper(i, j - 1))

    return helper(len(s1), len(s2))
```

