def has_path(start_page, end_page, graph):
    if start_page == end_page:
        return True

    visited = set()
    stack = [start_page]

    while stack:
        current = stack.pop()
        if current == end_page:
            return True
        if current in visited:
            continue
        visited.add(current)

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                stack.append(neighbor)

    return False
