import json

def calculate_total_cost(json_string):
    if not isinstance(json_string, str):
        raise ValueError("Input must be a string.")

    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string.")

    if not isinstance(data, list):
        raise ValueError("JSON root must be a list.")

    result = {}

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item in the list must be a dictionary.")

        required_keys = {'name', 'price', 'quantity'}
        if not required_keys.issubset(item.keys()):
            raise ValueError("Each product dictionary must contain 'name', 'price', and 'quantity'.")

        name = item['name']
        price = item['price']
        quantity = item['quantity']

        if not isinstance(name, str):
            raise ValueError("Product 'name' must be a string.")

        if not isinstance(price, (int, float, str)):
            raise ValueError("Product 'price' must be a number or a string representing a number.")

        if not isinstance(quantity, (int, float, str)):
            raise ValueError("Product 'quantity' must be a number or a string representing a number.")

        try:
            price_val = float(price)
            quantity_val = float(quantity)
        except (TypeError, ValueError):
            raise ValueError("Product 'price' and 'quantity' must be valid numeric values.")

        if price_val < 0 or quantity_val < 0:
            raise ValueError("Product 'price' and 'quantity' must be non-negative.")

        total = price_val * quantity_val
        result[name] = round(total, 2)

    return result
