def convert_units(value, from_unit, to_unit):
    # Normalize unit names for comparison
    from_unit = from_unit.lower()
    to_unit = to_unit.lower()

    # Convert everything to a base unit first, then to the target unit
    # Base units: meters for length, celsius for temperature

    # Step 1: Convert input value to base unit
    if from_unit == "centimeters":
        value = value / 100.0  # to meters
    elif from_unit == "meters":
        pass  # already in base
    elif from_unit == "fahrenheit":
        # Convert Fahrenheit to Celsius
        value = (value - 32) * 5.0 / 9.0
    elif from_unit == "celsius":
        pass  # already in base
    else:
        raise ValueError(f"Unsupported from_unit: {from_unit}")

    # Step 2: Convert from base unit to target unit
    if to_unit == "centimeters":
        value = value * 100.0  # from meters to centimeters
    elif to_unit == "meters":
        pass  # already in base
    elif to_unit == "fahrenheit":
        # Convert Celsius to Fahrenheit
        value = value * 9.0 / 5.0 + 32
    elif to_unit == "celsius":
        pass  # already in base
    else:
        raise ValueError(f"Unsupported to_unit: {to_unit}")

    return value
