    color = [0] * n  # 0: uncolored, 1: color A, -1: color B

    def dfs(node, c):
        color[node] = c
        for neighbor in range(n):
            if graph[node][neighbor] == 1:
                if color[neighbor] == 0:
                    if not dfs(neighbor, -c):
                        return False
                elif color[neighbor] == c:
                    return False
        return True

    for i in range(n):
        if color[i] == 0:
            if not dfs(i, 1):
                return False
    return True
