def validate_ip(ip: str) -> str:
    def is_valid_ipv4(s: str) -> bool:
        parts = s.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part:
                return False
            if not part.isdigit():
                return False
            num = int(part)
            if num < 0 or num > 255:
                return False
            # Check for leading zeros: "0" is ok, "01" is not
            if len(part) > 1 and part[0] == '0':
                return False
        return True

    def is_valid_ipv6(s: str) -> bool:
        # Handle :: compression
        if '::' in s:
            if s.count('::') > 1:
                return False
            left, right = s.split('::')
            left_parts = left.split(':') if left else []
            right_parts = right.split(':') if right else []
            # Filter out empty strings that might appear from trailing/leading colons
            left_parts = [p for p in left_parts if p]
            right_parts = [p for p in right_parts if p]
            total_groups = len(left_parts) + len(right_parts)
            if total_groups > 7:
                return False
            groups = left_parts + right_parts
        else:
            groups = s.split(':')
            if len(groups) != 8:
                return False

        for group in groups:
            if not group:
                return False
            if len(group) > 4:
                return False
            try:
                int(group, 16)
            except ValueError:
                return False
        return True

    if is_valid_ipv4(ip):
        return 'IPv4'
    elif is_valid_ipv6(ip):
        return 'IPv6'
    else:
        return 'Invalid'
```

