def number_to_words(num: int) -> str:
    if num == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]
    scales = [
        "", "thousand", "million", "billion"
    ]

    def convert_under_thousand(n: int) -> str:
        if n == 0:
            return ""
        elif n < 20:
            return ones[n]
        elif n < 100:
            ten = tens[n // 10]
            rest = n % 10
            if rest == 0:
                return ten
            return f"{ten} {ones[rest]}"
        else:
            hundred = ones[n // 100]
            rest = n % 100
            if rest == 0:
                return f"{hundred} hundred"
            return f"{hundred} hundred {convert_under_thousand(rest)}"

    parts = []
    scale_index = 0

    while num > 0:
        chunk = num % 1000
        if chunk != 0:
            chunk_words = convert_under_thousand(chunk)
            if scale_index > 0:
                chunk_words += f" {scales[scale_index]}"
            parts.append(chunk_words)
        num //= 1000
        scale_index += 1

    return " ".join(reversed(parts))
```

