def convert_temperatures(temperatures, from_unit, to_unit):
    valid_units = {"C", "F", "K"}

    if from_unit not in valid_units or to_unit not in valid_units:
        raise ValueError("Invalid unit specified. Use 'C', 'F', or 'K'.")

    if from_unit == to_unit:
        return [float(t) for t in temperatures]

    def to_celsius(temp, unit):
        if unit == "C":
            return temp
        elif unit == "F":
            return (temp - 32) * 5 / 9
        elif unit == "K":
            return temp - 273.15

    def from_celsius(temp, unit):
        if unit == "C":
            return temp
        elif unit == "F":
            return temp * 9 / 5 + 32
        elif unit == "K":
            return temp + 273.15

    # Convert from source unit to Celsius, then from Celsius to target unit
    celsius_temps = [to_celsius(t, from_unit) for t in temperatures]
    result = [from_celsius(c, to_unit) for c in celsius_temps]

    return result
