    # Define complement mapping without using a dictionary
    # We will use if-elif-else to map each nucleotide to its complement
    def get_complement(nucleotide):
        if nucleotide == 'A':
            return 'T'
        elif nucleotide == 'T':
            return 'A'
        elif nucleotide == 'C':
            return 'G'
        elif nucleotide == 'G':
            return 'C'
        else:
            # Should not happen given the problem constraints
            return nucleotide

