    # Base case: if either string is empty, LCS length is 0
    if not s1 or not s2:
        return 0

    # If the last characters match, take 1 + LCS of the prefixes
    if s1[-1] == s2[-1]:
        return 1 + longest_common_subsequence(s1[:-1], s2[:-1])
    else:
        # If they don't match, take the maximum of:
        # 1. LCS of s1 without last char and s2
        # 2. LCS of s1 and s2 without last char
