        if isinstance(val1, dict) and isinstance(val2, dict):
            merged = {}
            all_keys = set(val1.keys()) | set(val2.keys())
            for k in all_keys:
                if k in val1 and k in val2:
                    merged[k] = collect_values(val1[k], val2[k])
