def sum_of_primes(n: int) -> int:
    if n <= 2:
        return 0

    # Sieve of Eratosthenes to find primes up to n-1
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if is_prime[i]:
            # Mark multiples of i starting from i*i
            start = i * i
            is_prime[start:n:i] = [False] * ((n - 1 - start) // i + 1)

