def circular_binary_search(numbers, target, lower=0, upper=None):
    if upper is None:
        upper = len(numbers) - 1

    if lower > upper:
        return None

    mid = (lower + upper) // 2

    if numbers[mid] == target:
        # Check if this is the first occurrence
        if mid == 0 or numbers[mid - 1] != target:
            return mid
        # If not first, search left half for earlier occurrence
        return circular_binary_search(numbers, target, lower, mid - 1)

    # Determine which half is sorted
    is_left_sorted = numbers[lower] <= numbers[mid]

    if is_left_sorted:
        if numbers[lower] <= target < numbers[mid]:
            return circular_binary_search(numbers, target, lower, mid - 1)
        else:
            return circular_binary_search(numbers, target, mid + 1, upper)
    else:
        # Right half is sorted
        if numbers[mid] < target <= numbers[upper]:
            return circular_binary_search(numbers, target, mid + 1, upper)
        else:
            return circular_binary_search(numbers, target, lower, mid - 1)
