def find_argument(options, mapping, default=None):
    """
    Recursively searches through a nested list of options and returns the argument
    corresponding to the first matching option found in the mapping.

    Args:
        options (list): A nested list of strings representing the options to search for.
        mapping (list): A list of tuples (option, argument) to match against.
        default: A default value to return if no match is found.

    Returns:
        str: The argument corresponding to the first matching option, or the default value.
    """
    for item in options:
        if isinstance(item, list):
            result = find_argument(item, mapping, default)
            if result is not None:
                return result
        elif isinstance(item, str):
            for opt, arg in mapping:
                if opt == item:
                    return arg
    return default
