def find_most_common_elements(numbers, n):
    # Manual counting without using built-in count or Counter
    counts = {}
    for num in numbers:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Convert to list of (element, count) tuples
    items = []
    for key, value in counts.items():
        items.append((key, value))

    # Manual sorting by count descending, then by element ascending for ties
    # We'll implement a simple selection sort to avoid built-in sort
    m = len(items)
    for i in range(m - 1):
        # Find index of max from i to end
        max_idx = i
        for j in range(i + 1, m):
            # Compare by count descending, then by element ascending
            if items[j][1] > items[max_idx][1] or \
               (items[j][1] == items[max_idx][1] and items[j][0] < items[max_idx][0]):
                max_idx = j
        # Swap
        items[i], items[max_idx] = items[max_idx], items[i]

    # Take top n (or all if fewer)
    result = {}
    limit = min(n, m)
    for i in range(limit):
        result[items[i][0]] = items[i][1]

    return result
