def prime_squares(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def count_ways(p):
        if p < 0:
            return 0
        count = 0
        limit = int(p ** 0.5)
        for a in range(limit + 1):
            b_sq = p - a * a
            b = int(b_sq ** 0.5)
            if b * b == b_sq:
                # Count unordered pairs {a, b}
                if a == b:
                    count += 1
                elif a < b:
                    count += 1
                # a > b cases are symmetric and already covered by a < b
        return count

    result = {}
    for num in range(2, n + 1):
        if is_prime(num):
            result[num] = count_ways(num)
    return result
