class FibonacciCache:
    def __init__(self):
        self.cache = {0: 0, 1: 1}

    def get(self, n):
        if n not in self.cache:
            self._compute_up_to(n)
        return self.cache[n]

    def _compute_up_to(self, n):
        for i in range(2, n + 1):
            self.cache[i] = self.cache[i - 1] + self.cache[i - 2]


def optimized_fibonacci(n):
    if n < 1:
        return []
    if n == 1:
        return [0]

    cache = FibonacciCache()
    result = [0] * n
    result[0] = cache.get(0)
    result[1] = cache.get(1)

    for i in range(2, n):
        result[i] = cache.get(i)

    return result
