import random
import math

class PoissonDistribution:
    def __init__(self, mean):
        if mean < 0:
            raise ValueError("Mean must be non-negative")
        self._mean = float(mean)

    def setMean(self, mean):
        if mean < 0:
            raise ValueError("Mean must be non-negative")
        self._mean = float(mean)

    def generate(self):
        if self._mean <= 0:
            return 0
        # Standard Poisson generation using the inverse transform method
        L = math.exp(-self._mean)
        k = 0
        p = 1.0
        while True:
            k += 1
            p *= random.random()
            if p < L:
                return k - 1
        # The loop will always return before hitting the cap because
        # the theoretical Poisson support is unbounded, but we enforce the cap below.

    def getMean(self):
        return self._mean


def dynamic_poisson(p, mean):
    if mean <= 0:
        return 0
    # Update the distribution's mean
    p.setMean(mean)
    # Generate a sample, but cap it at twice the mean
    value = p.generate()
    cap = int(2 * mean)
    if value > cap:
        # If the generated value exceeds the cap, we can either:
        # 1) Regenerate until it fits (may be inefficient for large means)
        # 2) Return the capped value
        # Following the spec's intent ("ensuring that the generated number does not exceed twice the current mean"),
        # we regenerate until the condition is satisfied.
        while value > cap:
            value = p.generate()
    return value
