def get_all_subsidiaries(orgs, relationships):
    # Build adjacency list for parent -> children
    children = {}
    for org in orgs:
        children[org] = set()

    for parent, child in relationships:
        if parent in children:
            children[parent].add(child)
        else:
            # If parent is not in orgs list, still track it if it appears as a parent
            children[parent] = {child}

    # Initialize result set with input organizations
    result = set(orgs)

    # Perform BFS/DFS to traverse up to 20 levels and avoid cycles
    visited = set()
    queue = list(orgs)  # Start traversal from all input organizations

    # Track depth to limit to 20 levels
    # We'll use a queue of (node, depth)
    queue_with_depth = [(org, 0) for org in orgs]

    while queue_with_depth:
        current_org, depth = queue_with_depth.pop(0)

        if depth > 20:
            continue

        if current_org in visited:
            continue
        visited.add(current_org)

        # Add to result if not already present
        result.add(current_org)

        # Traverse children
        if current_org in children:
            for child in children[current_org]:
                if child not in visited:
                    queue_with_depth.append((child, depth + 1))

    return result
```

