def update_config(config_json, config_yaml):
    def get_leaf_hash(obj):
        """
        Compute a hash based on all leaf values in a nested dictionary.
        Leaves are values that are not dictionaries.
        """
        if isinstance(obj, dict):
            # Sort keys to ensure consistent ordering for hashing
            items = sorted(obj.items())
            return tuple(get_leaf_hash(k) if isinstance(k, dict) else k for k, v in items)
        else:
            return obj

    def update_recursive(json_dict, yaml_dict, count):
        if not isinstance(json_dict, dict) or not isinstance(yaml_dict, dict):
            return count

        for key in json_dict:
            if key not in yaml_dict:
                # Key does not exist in yaml; skip (spec says only update if key exists in both)
                continue

            json_val = json_dict[key]
            yaml_val = yaml_dict[key]

            if isinstance(json_val, dict) and isinstance(yaml_val, dict):
                # Compare leaf hashes
                if get_leaf_hash(json_val) != get_leaf_hash(yaml_val):
                    # Recursively update nested dict
                    count = update_recursive(json_val, yaml_val, count)
                # else: leaf hashes match, no update needed
            elif json_val != yaml_val:
                # Values differ and are not nested dicts
                yaml_dict[key] = json_val
                count += 1

        return count

    updated_count = 0
    return update_recursive(config_json, config_yaml, updated_count)
