def convert_to_base(number, base):
    if not (2 <= base <= 36):
        return "Invalid base"

    if number == 0:
        return "0"

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []

    while number > 0:
        remainder = number % base
        result.append(digits[remainder])
        number //= base

    # The digits were collected in reverse order
    return ''.join(reversed(result))
