def initialize_lcp(nodes, obstacles):
    """
    Initializes a data structure to compute Least Cost Paths (LCPs) between nodes.

    Parameters:
        nodes (list of tuple): List of (x, y) coordinates for each node.
        obstacles (list of tuple): List of (x, y) coordinates for obstacles.

    Returns:
        dict: A dictionary mapping node names to their source coordinates and destination nodes.
        list: A list of node names in the order they appear in the input list.
    """
    node_names = [f'n{i}' for i in range(len(nodes))]
    lcp_dict = {}

    for i, name in enumerate(node_names):
        src_coords = nodes[i]
        lcp_dict[name] = {
            'src': src_coords,
            'dsts': {}
        }

        for j, other_name in enumerate(node_names):
            if i != j:
                lcp_dict[name]['dsts'][other_name] = {
                    'coords': nodes[j]
                }

    return lcp_dict, node_names
