def can_place_tile(m, n, a, b, x, y, grid):
    # Check if the starting position is within bounds
    if x < 0 or y < 0 or x >= n or y >= m:
        return False

    # Define the two possible orientations: (a, b) and (b, a)
    orientations = [(a, b), (b, a)]

    for width, height in orientations:
        # Check if the tile fits within the wall boundaries starting at (x, y)
        if x + width > n or y + height > m:
            continue

        # Check for overlap with existing tiles
        can_place = True
        for dy in range(height):
            for dx in range(width):
                if grid[y + dy][x + dx] == 1:
                    can_place = False
                    break
            if not can_place:
                break

        if can_place:
            return True

    return False
