def capitalize_titles(titles):
    articles = {"a", "an", "the"}
    conjunctions = {"and", "but", "or", "nor", "for", "yet", "so"}
    prepositions = {
        "about", "above", "across", "after", "against", "along", "among", "around",
        "at", "before", "behind", "below", "beneath", "beside", "between", "beyond",
        "by", "down", "during", "except", "from", "in", "inside", "into", "like",
        "near", "of", "off", "on", "onto", "out", "outside", "over", "past",
        "since", "through", "throughout", "till", "to", "toward", "under", "underneath",
        "until", "up", "upon", "with", "within", "without"
    }
    small_words = articles | conjunctions | prepositions

    def capitalize_word(word, index, total_words):
        word = word.strip()
        if not word:
            return word

        # First word and last word are always capitalized
        if index == 0 or index == total_words - 1:
            return word.capitalize()

        # Check if the word is a small word (article, conjunction, preposition) with < 5 letters
        if len(word) < 5 and word.lower() in small_words:
            return word.lower()

        # Otherwise, capitalize the first letter
        return word.capitalize()

    def process_title(title):
        words = title.split()
        if not words:
            return title

        capitalized_words = [
            capitalize_word(word, i, len(words))
            for i, word in enumerate(words)
        ]
        return " ".join(capitalized_words)

    return [process_title(title) for title in titles]
