import math

def trimmed_mean(arr):
    n = len(arr)

    # If fewer than 10 elements, return NaN
    if n < 10:
        return float('nan')

    # Check for non-finite numbers (NaN or Inf)
    for x in arr:
        if not math.isfinite(x):
            return float('nan')

    # Sort the array
    sorted_arr = sorted(arr)

    # Calculate number of elements to trim from each end (10%)
    trim_count = max(1, int(n * 0.10))

    # Slice the array to remove the lowest and highest trim_count elements
    trimmed_arr = sorted_arr[trim_count:n - trim_count]

    # Compute the mean of the remaining elements
    if len(trimmed_arr) == 0:
        return float('nan')

    return sum(trimmed_arr) / len(trimmed_arr)
