def optimizedPow(x, n):
    """
    Computes x^n using Exponentiation by Squaring with memoization.
    Handles positive, negative, and zero exponents.
    """
    if n == 0:
        return 1.0

    # Handle negative exponent by inverting base and using positive exponent
    if n < 0:
        x = 1.0 / x
        n = -n

    memo = {}

    def power(base, exp):
        if exp == 0:
            return 1.0
        if exp in memo:
            return memo[exp]

        half = power(base, exp // 2)
        result = half * half

        if exp % 2 == 1:
            result *= base

        memo[exp] = result
        return result

    return power(x, n)
