def unique_union(list_1, list_2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    seen = set()
    result = []

    # Process list_1: add all unique elements in order of first appearance
    for x in list_1:
        if x not in seen:
            seen.add(x)
            result.append(x)

    # Process list_2: add only if not in list_1 and is prime
    for x in list_2:
        if x not in seen and is_prime(x):
            seen.add(x)
            result.append(x)

    return result
