def calculate_median(hours):
    # Make a copy to avoid modifying the original list
    arr = hours[:]
    n = len(arr)

    if n == 0:
        return 0.0

    # Sort the list manually using a simple bubble sort
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap
                arr[j], arr[j + 1] = arr[j + 1], arr[j]

    if n % 2 == 1:
        median = float(arr[n // 2])
    else:
        mid1 = arr[n // 2 - 1]
        mid2 = arr[n // 2]
        median = (mid1 + mid2) / 2.0

    return round(median, 6)
