class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def minValueWithMinimumBound(root, K):
    if root is None:
        return -1

    result = -1
    current = root

    while current:
        if current.val >= K:
            # This is a candidate; try to find a smaller one in the left subtree
            result = current.val
            current = current.left
        else:
            # current.val < K, need to go right
            current = current.right

    return result

def build_tree_from_input(n, values):
    if n == 0:
        return None
    root = TreeNode(values[0])
    for val in values[1:]:
        node = root
        while True:
            if val < node.val:
                if node.left is None:
                    node.left = TreeNode(val)
                    break
                node = node.left
            else:
                if node.right is None:
                    node.right = TreeNode(val)
                    break
                node = node.right
    return root

def main():
    import sys
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    values = []
    for _ in range(n):
        values.append(int(next(iterator)))

    k = int(next(iterator))

    root = build_tree_from_input(n, values)
    print(minValueWithMinimumBound(root, k))

if __name__ == "__main__":
    main()
```

