def safe_retrieve_value(data_dict, key):
    try:
        value = data_dict.get(key)
        if value is None:
            return None

        if isinstance(value, str):
            if value == '':
                return value
            # Try to convert to int first
            try:
                int_val = int(value)
                return int_val
            except ValueError:
                pass
            # Try to convert to float
            try:
                float_val = float(value)
                # If it's a whole number float, we still return float as per spec example '5.9' -> 5.9
                # But if the original string was '0', we already handled it above via int conversion
                # However, spec says if value is '0' return integer 0, which int('0') does
                # So we only return float if int conversion failed
                return float_val
            except ValueError:
                return value
        else:
            # If it's already an int or float, return as is
            return value
    except Exception:
        return None
