def sort_dicts(dicts, criteria):
    def sort_key(item):
        key_parts = []
        for key, ascending in criteria:
            value = item[key]
            # For descending order, negate the value if it's numeric; otherwise, use a wrapper
            if isinstance(value, (int, float)):
                key_parts.append(-value if not ascending else value)
            else:
                # For non-numeric types, reverse order by using a custom comparison trick
                if not ascending:
                    # We'll handle this by reversing the sort order via a custom key
                    key_parts.append((None, value))  # Placeholder; we'll use a different approach below
                else:
                    key_parts.append(value)
        return key_parts

    # Since Python's sort key cannot directly reverse non-numeric types easily,
    # we'll use a different strategy: sort step by step using stable sort.
    # However, to keep it simple and correct for all comparable types, we'll use functools.cmp_to_key.
    from functools import cmp_to_key

    def compare(item1, item2):
        for key, ascending in criteria:
            val1 = item1[key]
            val2 = item2[key]
            if val1 < val2:
                return -1 if ascending else 1
            elif val1 > val2:
                return 1 if ascending else -1
        return 0

    return sorted(dicts, key=cmp_to_key(compare))
