def decode_base64_attrs(data: Union[Dict, List, str, int, float, bool, None]) -> Any:
    """
    Recursively decodes base64 encoded strings in a nested dictionary or list structure.
    Only strings that are valid base64 will be decoded. Invalid base64 strings are left unchanged.

    Args:
        data: A nested structure containing dictionaries, lists, and strings.

    Returns:
        The same structure with base64 strings decoded to UTF-8.
    """
    if isinstance(data, dict):
        return {key: decode_base64_attrs(value) for key, value in data.items()}
