def transform_filters_to_sql(filters):
    """
    Converts a nested dictionary of filter conditions into a SQL WHERE clause string.

    Args:
        filters (dict): A dictionary where keys are field names and values are dictionaries
                        containing filter operators and their thresholds.

    Returns:
        str: A SQL WHERE clause string.
    """
    conditions = []

    for field, conditions_dict in filters.items():
        for op, value in conditions_dict.items():
            if op == "^lt":
                conditions.append(f"{field} < {value}")
            elif op == "^lte":
                conditions.append(f"{field} <= {value}")
            elif op == "^gt":
                conditions.append(f"{field} > {value}")
