def fibonacci(n: int) -> int:
    """
    Compute the n-th Fibonacci number using recursion with memoization.
    Works efficiently for 0 <= n <= 1000.
    """
    memo = {}

    def fib(k: int) -> int:
        if k in memo:
            return memo[k]
        if k == 0:
            result = 0
        elif k == 1:
            result = 1
        else:
            result = fib(k - 1) + fib(k - 2)
        memo[k] = result
        return result

