def shortest_path_in_maze(maze):
    if not maze or not maze[0]:
        return -1

    n = len(maze)
    m = len(maze[0])

    # If start or end is blocked, no path exists
    if maze[0][0] == 1 or maze[n - 1][m - 1] == 1:
        return -1

    # dp[i][j] = shortest path length to reach cell (i, j)
    # Initialize with infinity
    dp = [[float('inf')] * m for _ in range(n)]
    dp[0][0] = 1  # Starting cell counts as length 1

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 1:
                continue  # Blocked cell, skip

            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + 1)

    return dp[n - 1][m - 1] if dp[n - 1][m - 1] != float('inf') else -1
