def count_connected_components(graph):
    if not graph:
        return 0

    visited = set()
    components = 0

    # Ensure all nodes are keys in the graph (handle isolated nodes not listed as keys)
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    for node in all_nodes:
        if node not in visited:
            components += 1
            # Start BFS/DFS from this node
            stack = [node]
            while stack:
                current = stack.pop()
                if current in visited:
                    continue
                visited.add(current)
                # Add neighbors to stack if they exist in the graph
                if current in graph:
                    for neighbor in graph[current]:
                        if neighbor not in visited:
                            stack.append(neighbor)

    return components
