    # Check exact "True" or "False" (case-sensitive)
    if s == "True" or s == "False":
        return True

    # Check exact "1" or "0"
    if s == "1" or s == "0":
        return True

    # Check case-insensitive "yes" or "no"
    if s_lower == "yes" or s_lower == "no":
        return True

    # Check case-insensitive "on" or "off"
    if s_lower == "on" or s_lower == "off":
        return True

    # Check if s is a permutation of "fals" (case-insensitive)
    # Length must be 4 and characters must match multiset of 'f','a','l','s'
    if len(s) == 4:
        s_chars = sorted(s_lower)
        if s_chars == ['a', 'f', 'l', 's']:
            return True

