            try:
                val = int(part, 8)
            except ValueError:
                return 0
            base = 8
        else:
            # Decimal
            # No leading zeros allowed unless the number is exactly "0"
            if len(part) > 1 and part[0] == '0':
                return 0
            try:
                val = int(part, 10)
            except ValueError:
                return 0
            base = 10

        # Check range [0, 255]
        if val < 0 or val > 255:
            return 0

