def parse_cookie(cookie_str):
    """
    Parses a custom HTTP cookie string into a dictionary.

    Format: <cookie_name>=<cookie_value>; <cookie_attribute>=<cookie_attribute_value>; ...

    Returns:
        dict: {cookie_name: {'value': cookie_value, 'attr1': attr_value1, ...}}
    """
    cookie_str = cookie_str.strip()
    if not cookie_str:
        return {}

    # Split by semicolon to separate the main cookie part from attributes
    parts = cookie_str.split(';')
    main_part = parts[0].strip()
    attributes = [p.strip() for p in parts[1:] if p.strip()]

    if '=' not in main_part:
        raise ValueError("Invalid cookie format: missing '=' in cookie name/value pair")

    cookie_name, cookie_value = main_part.split('=', 1)
    cookie_name = cookie_name.strip()
    cookie_value = cookie_value.strip()

    result = {
        'value': cookie_value
    }

    for attr in attributes:
        if '=' in attr:
            attr_name, attr_value = attr.split('=', 1)
            result[attr_name.strip()] = attr_value.strip()
        else:
            # Attribute without value
            result[attr] = ''

    return {cookie_name: result}
