```python
def matrix_multiply(A, B):
    # Check if matrices are valid lists of lists
    if not isinstance(A, list) or not isinstance(B, list):
        return "Invalid matrix dimensions for multiplication."

    if len(A) == 0 or len(B) == 0:
        return "Invalid matrix dimensions for multiplication."

    # Check if all rows in A and B are lists
    if not all(isinstance(row, list) for row in A) or not all(isinstance(row, list) for row in B):
        return "Invalid matrix dimensions for multiplication."

    rows_A = len(A)
    cols_A = len(A[0])
    rows_B = len(B)
    cols_B = len(B[0])

    # Check if all rows in A have the same length and all rows in B have the same length
    if not all(len(row) == cols_A for row in A) or not all(len(row) == cols_B for row in B):
        return "Invalid matrix dimensions for multiplication."

    # Check if multiplication is possible (cols_A == rows_B)
    if cols_A != rows_B:
        return "Invalid matrix dimensions for multiplication."

    # Initialize result matrix
    result = [[0 for _ in range(cols_B)] for _ in range(rows_A)]

    # Perform matrix multiplication
    for i in range(rows_A):
        for j in range(cols_B):
            for k in range(cols_A):
                result[i][j] += A[i][k] * B[k][j]

    return result
```

