```python
def are_identical_trees(tree1, tree2):
    """
    Determine if two binary trees are structurally identical with same node values.

    Input:
        tree1, tree2: List representing level-order traversal of binary trees.
                      None indicates a missing node.

    Output:
        True if trees are identical, False otherwise.
    """
    def build_tree(nodes, index):
        """Recursively build a tree node from level-order list."""
        if index >= len(nodes) or nodes[index] is None:
            return None
        node = {'val': nodes[index], 'left': None, 'right': None}
        node['left'] = build_tree(nodes, 2 * index + 1)
        node['right'] = build_tree(nodes, 2 * index + 2)
        return node

    def is_identical(node1, node2):
        if node1 is None and node2 is None:
            return True
        if node1 is None or node2 is None:
            return False
        if node1['val'] != node2['val']:
            return False
        return is_identical(node1['left'], node2['left']) and \
               is_identical(node1['right'], node2['right'])

    # Handle empty lists explicitly
    if not tree1 and not tree2:
        return True
    if not tree1 or not tree2:
        return False

    root1 = build_tree(tree1, 0)
    root2 = build_tree(tree2, 0)

    return is_identical(root1, root2)
```

