import re

def unescape_html_entities_and_url(escaped_text):
    # First, decode URL-encoded characters (%XX)
    # We use a regex to find all %XX patterns and decode them
    def url_decode(match):
        try:
            return bytes.fromhex(match.group(1)).decode('utf-8')
        except (ValueError, UnicodeDecodeError):
            # If decoding fails, return the original match
            return match.group(0)

    # Replace all %XX with their decoded characters
    decoded_url = re.sub(r'%([0-9A-Fa-f]{2})', url_decode, escaped_text)

    # Now decode HTML entities
    # html.unescape handles standard HTML entities like &lt;, &gt;, &amp;, etc.
    # It also handles named entities like &nbsp;
    decoded_html = html.unescape(decoded_url)

    return decoded_html
