from typing import List, Dict, Any, Callable

def evaluate_expression(expression: List[Any], symbol_table: Dict[str, Callable]) -> float:
    """
    Evaluates an arithmetic expression given as a list of integers and operator strings.
    Supports +, -, *, / with standard precedence and left-to-right associativity.
    Division returns a float.
    """
    if not expression:
        raise ValueError("Expression cannot be empty.")

    # Validate that all elements are either int/float or a known operator string
    for item in expression:
        if isinstance(item, str):
            if item not in symbol_table:
                raise ValueError(f"Unknown operator: {item}")
        elif not isinstance(item, (int, float)):
            raise ValueError(f"Invalid operand type: {type(item)}")

    # We'll use two stacks: values and operators
    values: List[float] = []
    ops: List[str] = []

    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    def apply_op():
        if len(ops) < 1:
            return
        op = ops.pop()
        if len(values) < 2:
            raise ValueError("Insufficient operands for operator.")
        b = values.pop()
        a = values.pop()
        func = symbol_table[op]
        result = func(a, b)
        values.append(result)

    def next_op_precedence():
        if not ops:
            return 0
        return precedence.get(ops[-1], 0)

    for token in expression:
        if isinstance(token, (int, float)):
            values.append(float(token))
        else:
            # Operator
            while (ops and ops[-1] != '(' and
                   precedence.get(ops[-1], 0) >= precedence.get(token, 0)):
                apply_op()
            ops.append(token)

    while ops:
        apply_op()

    if len(values) != 1:
        raise ValueError("Invalid expression: too many operands.")

    return values[0]
