def safe_cast(x, target_type):
    if x is None:
        if target_type is int:
            # Smallest possible integer value (two's complement min for platform)
            return -(1 << (x.bit_length() if hasattr(x, 'bit_length') else 64))
        elif target_type is float:
            # Smallest positive normalized float
            return float.fromhex('0x1.0p-1022')
        elif target_type is str:
            # Shortest non-empty ASCII string with smallest char value
            return '\x00'
        elif target_type is bool:
            # Lowest truthiness boolean
            return False
        elif target_type is list:
            return []
