def propagate_property(grid, key, initial_value, propagation_rules):
    if not grid:
        return grid

    rule = propagation_rules.get(key)
    if rule is None:
        # If no rule is provided, just set the initial value in the first row and copy it down
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                grid[i][j][key] = initial_value
        return grid

    # Propagate row by row
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if i == 0:
                # First row: use initial value
                grid[i][j][key] = initial_value
            else:
                # Get value from the cell above
                value_above = grid[i - 1][j].get(key)
                # Apply propagation rule
                new_value = rule(value_above)
                grid[i][j][key] = new_value

    return grid
