def rank_matrix(matrix):
    if not matrix or not matrix[0]:
        return matrix

    # Flatten the matrix while keeping track of original positions
    flat = []
    for r in range(len(matrix)):
        for c in range(len(matrix[r])):
            flat.append((matrix[r][c], r, c))

    # Sort manually using selection sort (no built-in sort)
    n = len(flat)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if flat[j][0] < flat[min_idx][0]:
                min_idx = j
            elif flat[j][0] == flat[min_idx][0]:
                # Tie-breaker: smaller row index, then smaller column index
                if (flat[j][1], flat[j][2]) < (flat[min_idx][1], flat[min_idx][2]):
                    min_idx = j
        flat[i], flat[min_idx] = flat[min_idx], flat[i]

    # Assign ranks
    rank_map = {}
    current_rank = 1
    for i in range(n):
        val, r, c = flat[i]
        if val not in rank_map:
            rank_map[val] = current_rank
            current_rank += 1

    # Build result matrix
    result = []
    for r in range(len(matrix)):
        row = []
        for c in range(len(matrix[r])):
            row.append(rank_map[matrix[r][c]])
        result.append(row)

    return result
