import re

def convert_keys_to_snake_case(obj):
    """
    Recursively converts all dictionary keys to snake_case.
    - Strings, numbers, booleans, None, and lists are preserved as-is.
    - Dictionaries have their keys converted to snake_case and values processed recursively.
    """

    def to_snake_case(key):
        # Handle non-string keys by converting them to string first, then applying snake_case logic
        if not isinstance(key, str):
            return str(key)

        # Insert underscore before uppercase letters that follow lowercase letters or numbers
        s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', key)
        # Insert underscore before uppercase letters that are followed by lowercase letters
        # This handles cases like "XMLParser" -> "xml_parser"
        s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
        # Convert to lowercase
        return s.lower()

    if isinstance(obj, dict):
        return {
            to_snake_case(k): convert_keys_to_snake_case(v)
            for k, v in obj.items()
        }
    elif isinstance(obj, list):
        return [convert_keys_to_snake_case(item) for item in obj]
    else:
        # Return primitive values unchanged
        return obj
