def detect_cycles(graph):
    """
    Detects if a directed graph contains any cycle.

    Args:
        graph (dict): Adjacency list where keys are nodes and values are lists of neighbors.

    Returns:
        bool: True if a cycle exists, False otherwise.
    """
    # Initialize states: 0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited
    state = {node: 0 for node in graph}

    def has_cycle(node):
        if state[node] == 1:
            return True  # Back edge found -> cycle
        if state[node] == 2:
            return False  # Already fully processed

        state[node] = 1  # Mark as currently visiting

        for neighbor in graph.get(node, []):
            if neighbor not in state:
                # Node exists as a neighbor but not in our node set (e.g., isolated incoming edge)
                state[neighbor] = 0
                if has_cycle(neighbor):
                    return True
            else:
                if has_cycle(neighbor):
                    return True

        state[node] = 2  # Mark as fully visited
        return False

    # Check all nodes to handle disconnected components
    for node in graph:
        if state[node] == 0:
            if has_cycle(node):
                return True

    return False
