def numTrees(n):
    memo = {}

    def count_trees(k):
        if k <= 1:
            return 1
        if k in memo:
            return memo[k]

        total = 0
        for root in range(1, k + 1):
            left_count = root - 1
            right_count = k - root
            total += count_trees(left_count) * count_trees(right_count)

        memo[k] = total
        return total

    return count_trees(n)
```

