def sum_of_integers_in_string(string: str, separator: str) -> int:
    if not separator:
        return 0

    total = 0
    current_num = ""
    in_number = False

    for char in string:
        if char == separator:
            if in_number and current_num:
                try:
                    total += int(current_num)
                except ValueError:
                    pass
                current_num = ""
                in_number = False
        elif char.isdigit() or char == '-':
            if char == '-' and (in_number or not current_num):
                # Allow '-' only if we are starting a new number or continuing one
                if in_number:
                    # If we were already in a number, this '-' is invalid unless it's part of a multi-digit negative
                    # But since we reset on separator, this case shouldn't happen with valid logic below
                    pass
                else:
                    current_num = "-"
                    in_number = True
            elif char.isdigit():
                if not in_number:
                    current_num = ""
                current_num += char
                in_number = True
        else:
            if in_number and current_num:
                try:
                    total += int(current_num)
                except ValueError:
                    pass
                current_num = ""
                in_number = False

    # Process the last number if any
    if in_number and current_num:
        try:
            total += int(current_num)
        except ValueError:
            pass

    return total
