def coordinate_generator(coord_range):
    import re

    # Remove surrounding parentheses if present
    s = coord_range.strip()
    if s.startswith('(') and s.endswith(')'):
        s = s[1:-1]

    # Split into x and y parts
    parts = s.split(',')
    if len(parts) != 2:
        raise ValueError("Invalid coordinate range format. Expected format: (x_range, y_range)")

    def parse_range(part):
        part = part.strip()
        if ':' in part:
            start_str, end_str = part.split(':')
            start = int(start_str.strip())
            end = int(end_str.strip())
            # Ensure start <= end
            if start > end:
                start, end = end, start
            return range(start, end + 1)
        else:
            # Single coordinate
            val = int(part.strip())
            return range(val, val + 1)

    x_range = parse_range(parts[0])
    y_range = parse_range(parts[1])

    result = []
    for x in x_range:
        for y in y_range:
            result.append((x, y))

    return result
