import math
from abc import ABC, abstractmethod
from typing import Any, Callable, Dict

class Calculator(ABC):
    def __init__(self, precision: int):
        self.precision = precision
        self._methods: Dict[str, Callable] = {}

    def _round_result(self, value: float) -> float:
        return round(value, self.precision)

    def add_method(self, name: str, func: Callable) -> None:
        self._methods[name] = func

    def __call__(self, name: str, *args, **kwargs) -> Any:
        if name in self._methods:
            result = self._methods[name](*args, **kwargs)
            if isinstance(result, float):
                return self._round_result(result)
            return result
        raise AttributeError(f"Method '{name}' not found.")

class BasicCalculator(Calculator):
    def add(self, a: float, b: float) -> float:
        return self._round_result(a + b)

    def subtract(self, a: float, b: float) -> float:
        return self._round_result(a - b)

    def multiply(self, a: float, b: float) -> float:
        return self._round_result(a * b)

    def divide(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Division by zero")
        return self._round_result(a / b)

class ScientificCalculator(BasicCalculator):
    def __init__(self, precision: int, angle_mode: str):
        if angle_mode not in ("degrees", "radians"):
            raise ValueError("angle_mode must be 'degrees' or 'radians'")
        super().__init__(precision)
        self.angle_mode = angle_mode

    def power(self, base: float, exp: float) -> float:
        return self._round_result(base ** exp)

    def sqrt(self, x: float) -> float:
        if x < 0:
            raise ValueError("Square root of negative number")
        return self._round_result(math.sqrt(x))

    def sin(self, x: float) -> float:
        if self.angle_mode == "degrees":
            x = math.radians(x)
        return self._round_result(math.sin(x))

