        self.val = val
        self.left = left
        self.right = right

def findPath(rootNode):
    if rootNode is None:
        return []

    visited = []
    stack = [rootNode]

    while stack:
        node = stack[-1]
        if node.left is not None:
            stack.append(node.left)
        else:
            # No left child: visit current node
            visited.append(node.val)
            # Pop and try right child
            stack.pop()
            if node.right is not None:
                stack.append(node.right)
            else:
                # If no right child, continue popping until we find a node with a right child or stack empty
                while stack and stack[-1].right is None:
                    stack.pop()
                if stack:
                    # Move to right child of the new top
                    stack[-1].right = None  # Prevent re-visiting this right child
                    stack.append(stack[-1].right)
                else:
                    stack.pop()

    return visited
```

