def prime_factorization(n, primes):
    if n <= 1:
        return {}

    # Remove duplicates and sort primes for efficiency
    unique_primes = sorted(set(primes))

    result = {}
    temp = n

    for p in unique_primes:
        if p * p > temp:
            break
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            result[p] = count

    # If temp > 1 after trying all given primes, it means n has a prime factor
    # not in the provided list, so we cannot fully factorize n with the given primes.
    if temp > 1:
        return {}

    return result
