def is_perfect_square(num: int) -> bool:
    if num < 0:
        return False
    if num == 0:
        return True

    # Use integer square root via binary search to avoid floating-point issues
    left, right = 1, num
    while left <= right:
        mid = (left + right) // 2
        sq = mid * mid
        if sq == num:
            return True
        elif sq < num:
            left = mid + 1
        else:
            right = mid - 1
    return False
```

