def binary_search_recursive(lst, n):
    def helper(low, high, direction):
        # direction: 1 for left-first, -1 for right-first
        if low > high:
            return False

        mid = (low + high) // 2

        if lst[mid] == n:
            return True

        if lst[mid] < n:
            # Target is in the right half
            if direction == 1:
                # Prefer left first, but target is not in left, so go right
                return helper(mid + 1, high, -1)
            else:
                # Prefer right first, so go right
                return helper(mid + 1, high, 1)
        else:  # lst[mid] > n
            # Target is in the left half
            if direction == 1:
                # Prefer left first, so go left
                return helper(low, mid - 1, -1)
            else:
                # Prefer right first, but target is not in right, so go left
                return helper(low, mid - 1, 1)

    # Start with direction 1 (left-first)
    return helper(0, len(lst) - 1, 1)
