def is_prime_recursive(n, divisor=None):
    # Handle edge cases
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Initialize divisor if not provided
    if divisor is None:
        divisor = 3

    # Base case: if divisor squared exceeds n, then n is prime
    if divisor * divisor > n:
        return True

    # Recursive step: check if divisor divides n
    if n % divisor == 0:
        return False

    # Recurse with the next odd number
    return is_prime_recursive(n, divisor + 2)
