def sort_and_group(tuples_list):
    # Manual implementation of sorting by category (bubble sort)
    n = len(tuples_list)
    if n == 0:
        return

    # Sort the list of tuples by category (first element)
    for i in range(n):
        for j in range(0, n - i - 1):
            if tuples_list[j][0] > tuples_list[j + 1][0]:
                tuples_list[j], tuples_list[j + 1] = tuples_list[j + 1], tuples_list[j]

    # Manual grouping without using built-in grouping functions
    current_category = None
    current_values = []

    for category, value in tuples_list:
        if current_category is None:
            current_category = category
            current_values = [value]
        elif current_category == category:
            current_values.append(value)
        else:
            # Yield the previous group
            yield (current_category, current_values)
            # Start a new group
            current_category = category
            current_values = [value]

    # Yield the last group
    if current_category is not None:
        yield (current_category, current_values)
