class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def is_empty(self):
        return len(self._items) == 0


def evaluate_postfix(expression: str) -> int:
    stack = Stack()
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            if stack.is_empty():
                raise ValueError("Invalid postfix expression: not enough operands")
            right = stack.pop()
            if stack.is_empty():
                raise ValueError("Invalid postfix expression: not enough operands")
            left = stack.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                # Integer division as per typical postfix evaluator behavior
                result = int(left / right)
            else:
                raise ValueError(f"Unsupported operator: {token}")

            stack.push(result)
        else:
            # Try to convert to int; if it fails, it's an error
            try:
                value = int(token)
            except ValueError:
                raise ValueError(f"Invalid token in expression: {token}")
            stack.push(value)

    if not stack.is_empty():
        return stack.pop()
    raise ValueError("Invalid postfix expression: extra operands")
```

