import re

def count_valid_ips(ips):
    def is_valid_ipv4(s):
        # Must have exactly 4 parts separated by dots
        parts = s.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part:
                return False
            # Check for leading zeros (except for "0" itself)
            if len(part) > 1 and part[0] == '0':
                return False
            if not part.isdigit():
                return False
            num = int(part)
            if num < 0 or num > 255:
                return False
        return True

    def is_valid_ipv6(s):
        # Remove leading/trailing whitespace if any (though input should be clean)
        s = s.strip()
        if not s:
            return False

        # IPv6 can have :: compression
        if s.count('::') > 1:
            return False

        # Replace :: with a placeholder to split
        if '::' in s:
            left, right = s.split('::')
            left_parts = left.split(':') if left else []
            right_parts = right.split(':') if right else []
            # Filter out empty strings that might result from leading/trailing colons
            left_parts = [p for p in left_parts if p]
            right_parts = [p for p in right_parts if p]
            total_parts = len(left_parts) + len(right_parts)
            if total_parts > 7:
                return False
            parts = left_parts + right_parts
        else:
            parts = s.split(':')
            if len(parts) != 8:
                return False

        for part in parts:
            if not part:
                return False
            # Each part must be 1 to 4 hex digits
            if len(part) > 4:
                return False
            if not re.fullmatch(r'[0-9a-fA-F]+', part):
                return False
        return True

    count = 0
    for ip in ips:
        ip = ip.strip()
        if not ip:
            continue
        if is_valid_ipv4(ip) or is_valid_ipv6(ip):
            count += 1
    return count
