```python
def convert_temperature(temp, conversion):
    intermediates = []

    def c_to_k(t):
        return t + 273.15

    def k_to_c(t):
        return t - 273.15

    def c_to_f(t):
        return t * 9.0 / 5.0 + 32.0

    def f_to_c(t):
        return (t - 32.0) * 5.0 / 9.0

    if conversion == "CtoF":
        k_temp = c_to_k(temp)
        intermediates.append(k_temp)
        result = k_to_c(k_temp)  # back to C
        result = c_to_f(result)
        return result

    elif conversion == "FtoC":
        k_temp = f_to_c(temp)
        intermediates.append(k_temp)
        result = k_to_c(k_temp)
        return result

    elif conversion == "CtoK":
        result = c_to_k(temp)
        return result

    elif conversion == "KtoC":
        result = k_to_c(temp)
        return result

    else:
        raise ValueError("Unsupported conversion type")
