def can_be_palindrome_by_deleting_one_char(s: str) -> bool:
    def is_palindrome(sub: str) -> bool:
        left, right = 0, len(sub) - 1
        while left < right:
            if sub[left].lower() != sub[right].lower():
                return False
            left += 1
            right -= 1
        return True

    left, right = 0, len(s) - 1
    while left < right:
        if s[left].lower() != s[right].lower():
            # Try skipping either the left or the right character
            return is_palindrome(s[left + 1:right + 1]) or is_palindrome(s[left:right])
        left += 1
        right -= 1

    return True
