def insert_sorted_pairs(pair, list_of_pairs):
    def sort_key(p):
        return p[0]**2 + p[1]**2, p[0]

    new_pair = pair
    left, right = 0, len(list_of_pairs)

    # Binary search for the insertion index
    while left < right:
        mid = (left + right) // 2
        if sort_key(list_of_pairs[mid]) < sort_key(new_pair):
            left = mid + 1
        else:
            right = mid

    # Insert at the found position
    return list_of_pairs[:left] + [new_pair] + list_of_pairs[left:]
```

